import test from 'node:test';
import assert from 'node:assert/strict';
import { unique } from '../src/unique.js';

const cases = [
  {
    name: 'repeated numbers retain negatives and zero in first-occurrence order',
    input: [3, -2, 0, 3, -2, 5, 0, -7, 5],
    expected: [3, -2, 0, 5, -7],
  },
  {
    name: 'repeated strings preserve empty strings and distinct capitalization',
    input: ['Beta', '', 'beta', 'Beta', 'Alpha', '', 'alpha', 'beta'],
    expected: ['Beta', '', 'beta', 'Alpha', 'alpha'],
  },
  {
    name: 'interleaved duplicates preserve first-occurrence order',
    input: ['z', 'a', 'z', 'm', 'a', 'b', 'm', 'z', 'b'],
    expected: ['z', 'a', 'm', 'b'],
  },
  {
    name: 'numbers and matching strings remain distinct',
    input: [1, '1', 0, '0', '1', 1, -2, '-2', 0, '0', -2, '-2'],
    expected: [1, '1', 0, '0', -2, '-2'],
  },
  { name: 'empty array', input: [], expected: [] },
  { name: 'number singleton', input: [0], expected: [0] },
  { name: 'string singleton', input: [''], expected: [''] },
  {
    name: 'already-unique array retains its order',
    input: ['last', 8, '', -3, 'first', 0],
    expected: ['last', 8, '', -3, 'first', 0],
  },
];

for (const { name, input, expected } of cases) {
  test(name, () => {
    const before = input.slice();
    const result = unique(input);

    assert.ok(Array.isArray(result));
    assert.notStrictEqual(result, input, 'must return a new array');
    assert.deepStrictEqual(result, expected);
    assert.deepStrictEqual(input, before, 'must not mutate the input');
  });
}

test('accepts a frozen duplicate-containing array without mutation', () => {
  const input = Object.freeze(['b', 1, 'b', '1', 1, '', '']);
  const result = unique(input);

  assert.ok(Array.isArray(result));
  assert.notStrictEqual(result, input);
  assert.deepStrictEqual(result, ['b', 1, '1', '']);
  assert.deepStrictEqual(input, ['b', 1, 'b', '1', 1, '', '']);
});

const invalidInputs = [
  ['undefined', undefined],
  ['null', null],
  ['zero', 0],
  ['negative number', -2],
  ['empty string', ''],
  ['nonempty string', 'aba'],
  ['false', false],
  ['true', true],
  ['plain object', {}],
  ['array-like object', { 0: 'a', 1: 'a', length: 2 }],
];

for (const [name, value] of invalidInputs) {
  test(`rejects ${name} with TypeError`, () => {
    assert.throws(() => unique(value), TypeError);
  });
}

